--
-- Name: v_motos_completo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_motos_completo AS
 SELECT m.id,
    ma.nombre AS marca,
    m.modelo,
    m.anio,
    t.nombre AS tipo,
    m.cilindrada_cc,
    m.potencia_hp,
    m.precio_usd,
    m.uso_recomendado,
    m.disponible_ec
   FROM ((public.motocicletas m
     JOIN public.marcas_moto ma ON ((m.marca_id = ma.id)))
     JOIN public.tipos_moto t ON ((m.tipo_id = t.id)))
  ORDER BY ma.nombre, m.modelo;


--
-- Name: vw_experimento_resumen; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_experimento_resumen AS
 SELECT u.id,
    u.nombre,
    u.email,
    u.grupo,
    u.rol,
    pre.score AS pretest_score,
    pre.total AS pretest_total,
    pre.creado_en AS pretest_fecha,
    pos.score AS postest_score,
    pos.total AS postest_total,
    pos.creado_en AS postest_fecha,
        CASE
            WHEN ((pre.score IS NOT NULL) AND (pos.score IS NOT NULL)) THEN (pos.score - pre.score)
            ELSE NULL::integer
        END AS ganancia_bruta,
        CASE
            WHEN ((pre.score IS NOT NULL) AND (pos.score IS NOT NULL) AND (pre.score > 0)) THEN round(((100.0 * ((pos.score - pre.score))::numeric) / (pre.score)::numeric), 1)
            ELSE NULL::numeric
        END AS mejora_pct
   FROM ((public.usuarios_auth u
     LEFT JOIN public.piloto_evaluaciones pre ON (((pre.usuario_id = u.id) AND ((pre.fase)::text = 'pretest'::text))))
     LEFT JOIN public.piloto_evaluaciones pos ON (((pos.usuario_id = u.id) AND ((pos.fase)::text = 'postest'::text))))
  WHERE ((u.rol)::text <> 'admin'::text);


